using UnityEngine; namespace Mojinloop.Gameplay { public sealed class HeroAnimationController:MonoBehaviour { static readonly int IsRunningHash=Animator.StringToHash("IsRunning"),IsAttackingHash=Animator.StringToHash("IsAttacking"); [SerializeField] Animator animator; public void Apply(HeroState state){if(animator==null)return;animator.SetBool(IsRunningHash,state==HeroState.Running);animator.SetBool(IsAttackingHash,state==HeroState.Attacking);} } }
